def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # The grid-wide uniform lines are the dividers.
    separators = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    divider = max(set(separators), key=separators.count)

    sep_rows = [r for r in sep_rows if grid[r][0] == divider]
    sep_cols = [c for c in sep_cols if grid[0][c] == divider]

    def intervals(size, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append(range(start, cut))
            start = cut + 1
        if start < size:
            result.append(range(start, size))
        return result

    row_blocks = intervals(h, sep_rows)
    col_blocks = intervals(w, sep_cols)

    counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != divider:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)
    signal = min(counts, key=counts.get)

    output = []
    for rs in row_blocks:
        out_row = []
        for cs in col_blocks:
            n = sum(grid[r][c] == signal for r in rs for c in cs)
            out_row.append(background if n == 1 else 1)
        output.append(out_row)
    return output
